using System.Collections.Generic;using UnityEngine;
namespace Blocklands {public partial class Sandbox
{
    public bool CreateCompleteSecretBase(){if(saveBlocked||CompanionReturnBlocked){Notice="请先结束游玩，或检查存档读取问题。";return false;}if(World.Region!=1&&!TravelTo(1))return false;RegisterLegacyVillageHome();OwnedHome home=null;foreach(var h in OwnedHomes)if(h.legacy&&h.region==1){home=h;break;}if(home==null){Player.Teleport(new Vector3(30,16.04f,45));if(!BuildNeighborHouse(28,50,true))return false;RegisterLegacyVillageHome();foreach(var h in OwnedHomes)if(h.legacy&&h.region==1){home=h;break;}}if(home==null)return false;Player.Teleport(new Vector3(30,16.04f,45));bool built=home.secretRoomVersion==1||AddHomeBasement(home,true);if(!built){Notice="房屋已在，但地下施工没有完成："+Notice;return false;}BuildSecretRooms();if(LifeWorkshopOpen)CloseLifeWorkshop();houseMenu=false;SetPaused(false);GoToSecretEntrance(home);Save();Notice="完整基地已真正建好：地面房屋、10×10地下室、楼梯、保险箱、储物柜、秋千和显示屏。看着木板门轻按H。";return true;}
    public bool AdaptCurrentShelter(){if(saveBlocked||InVoidRealms||CompanionReturnBlocked){Notice="请站在上方方块地区自己的木屋里，再改造。";return false;}Vector3 p=Player.transform.position;OwnedHome home=null;foreach(var h in OwnedHomes)if(h.region==World.Region&&!h.realm&&p.x>=h.x&&p.x<h.x+10&&p.z>=h.z&&p.z<h.z+10){home=h;break;}bool added=false;if(home==null){if(!FindShelterFloor(out int x,out int y,out int z)){Notice="脚下没有识别到自搭木地板。可改用“免费创建完整基地”，不会覆盖你的木屋。";return false;}home=new OwnedHome{region=World.Region,x=x,y=y,z=z};OwnedHomes.Add(home);added=true;}if(home.secretRoomVersion==1){BuildSecretRooms();GoToSecretEntrance(home);return true;}if(!AddHomeBasement(home,true)){if(added)OwnedHomes.Remove(home);return false;}if(LifeWorkshopOpen)CloseLifeWorkshop();GoToSecretEntrance(home);Save();Notice="这座木屋已经接上真实的10×10密室和保险箱。看着木板门轻按H下楼。";return true;}
    bool FindShelterFloor(out int hx,out int hy,out int hz){hx=hy=hz=0;Vector3 p=Player.transform.position;int cx=Mathf.FloorToInt(p.x),cz=Mathf.FloorToInt(p.z),bestY=0,bestCount=0;var candidates=new HashSet<Vector2Int>();for(int y=Mathf.FloorToInt(p.y)-3;y<=Mathf.FloorToInt(p.y)+1;y++){var row=new HashSet<Vector2Int>();for(int x=cx-10;x<=cx+10;x++)for(int z=cz-10;z<=cz+10;z++){var cell=new Vector3Int(x,y,z);if(!VoxelWorld.InBounds(cell)||World.Region==1&&VoxelWorld.VillageRenewable(cell)||World.Region==6&&VoxelWorld.CastleRenewable(cell))continue;if(World.Edits.TryGetValue(cell,out var b)&&(b==Block.Planks||b==Block.WoodTile||b==Block.StoneBricks))row.Add(new Vector2Int(x,z));}if(row.Count>bestCount){bestCount=row.Count;bestY=y;candidates=row;}}if(bestCount<8||bestY<8)return false;int minX=int.MaxValue,maxX=int.MinValue,minZ=int.MaxValue,maxZ=int.MinValue;foreach(var c in candidates){minX=Mathf.Min(minX,c.x);maxX=Mathf.Max(maxX,c.x);minZ=Mathf.Min(minZ,c.y);maxZ=Mathf.Max(maxZ,c.y);}hx=maxX-minX>=9?Mathf.Clamp(cx-5,minX,maxX-9):minX;hz=maxZ-minZ>=9?Mathf.Clamp(cz-5,minZ,maxZ-9):minZ;hy=bestY-1;return hx>=2&&hz>=2&&hx+11<VoxelWorld.Width&&hz+11<VoxelWorld.Depth;}
}}
